  EncryptResult cipher=p.client.wrap(1,new byte[]{1},0,1,18437);DecryptResult under=p.server.unwrap(1,Arrays.copyOf(cipher.output(),1),18437);check(under.status.equals("BUFFER_UNDERFLOW")&&!under.peerClosed,"Split header underflow distinct from close");DecryptResult overflow=p.server.unwrap(1,Arrays.copyOfRange(cipher.output(),1,cipher.produced),0);check(overflow.status.equals("BUFFER_OVERFLOW")&&overflow.consumed==0,"Forced unwrap overflow no consumption");DecryptResult recovered=p.server.unwrap(1,new byte[0],18437);check(Arrays.equals(recovered.output(),new byte[]{1}),"Overflow retry retained input exact");
