 static void rawRoundTrip(Pair p,int n,int chunk)throws Exception{
  byte[] plain=new byte[n];rnd.nextBytes(plain);ByteArrayOutputStream ciphertext=new ByteArrayOutputStream();int pos=0;while(pos<n){EncryptResult e=p.client.wrap(20,plain,pos,n-pos,18437);if(e.consumed==0)throw new AssertionError("Raw wrap no progress");pos+=e.consumed;ciphertext.write(e.output());}ByteArrayOutputStream result=new ByteArrayOutputStream();byte[] c=ciphertext.toByteArray();for(int q=0;q<c.length;){int step=chunk==0?c.length:chunk<0?1+rnd.nextInt(256):chunk;int end=Math.min(c.length,q+step);DecryptResult d=p.server.unwrap(20,Arrays.copyOfRange(c,q,end),18437);result.write(d.output());q=end;}while(p.server.pending()>0){DecryptResult d=p.server.unwrap(20,new byte[0],18437);if(d.consumed==0)throw new AssertionError("Raw incomplete");result.write(d.output());}DecryptResult tail=p.server.unwrap(20,new byte[0],18437);result.write(tail.output());prop(Arrays.equals(plain,result.toByteArray()),"Raw engine recovery n="+n);prop(p.server.pending()==0,"Raw no residue");bytes+=n;
 }
