  void toCore(String fixture,int ch,int flags)throws Exception{byte[] b=peerReceive(fixture(fixture),ch,flags);core.receive(new AaFrameWriter().encode(new AaFrame(ch,flags|3,-1,b)));}
  void outbound(int expected)throws Exception{for(byte[] raw:core.drainOutbound()){AaFrame f=new AaFrameParser(65535,1048576,128).feed(raw).get(0);byte[] wire=join(p.cp.encode(f.channel,f.flags&4,f.body(),true));List<AaMessageAssembler.Message> m=deliver(p.sp,wire,7,rnd);check(m.get(0).type==expected,"Encrypted core outbound type "+expected);check(Arrays.equals(m.get(0).bytes(),f.body()),"Specific outgoing discovery/control bytes exact");}}
